import { createContext, useContext, useState } from 'react';

type Item = { id: string; qty: number };
const CartContext = createContext<{ items: Item[]; add: (id: string) => void; remove: (id: string) => void }>(null as never);

export function CartProvider({ children }: { children: React.ReactNode }) {
  const [items, setItems] = useState<Item[]>([]);
  const add = (id: string) => setItems((current) => [...current, { id, qty: 1 }]);
  const remove = (id: string) => setItems((current) => current.filter((item) => item.id !== id));
  return <CartContext.Provider value={{ items, add, remove }}>{children}</CartContext.Provider>;
}

export const useCart = () => useContext(CartContext);

