import { useCart } from '../state/CartContext';

export function Basket() {
  const { items, remove } = useCart();
  return <ul>{items.map((item) => <li key={item.id}>{item.id}<button onClick={() => remove(item.id)}>Remove</button></li>)}</ul>;
}

