import { client } from './supabase.js';

export async function listInvoicesWithClients(ownerId) {
  const { data: invoices } = await client.from('invoices').select('*').eq('owner', ownerId);
  const result = [];
  for (const invoice of invoices ?? []) {
    const { data: found } = await client.from('clients').select('*').eq('id', invoice.client_id).single();
    result.push({ ...invoice, client: found });
  }
  return result;
}

