import { listInvoicesWithClients } from './invoices.js';

const app = express();
app.get('/api/invoices', async (request, response) => response.json(await listInvoicesWithClients(request.query.owner)));
app.get('/api/clients', async (_request, response) => response.json({ data: [] }));
app.get('/api/notes', async (_request, response) => response.json({ result: [], ok: true }));
export default app;

